// Medical Terminology Practice Test 5. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and using different terms from Practice Tests 1–4.
import {q, mix} from './q.js';
const EHR='Ehrlich, Medical Terminology for Health Professions', STAN='Stanhope & Turnbull, Introduction to Medical Terminology', TAB='Taber’s Cyclopedic Medical Dictionary';
const WP='Roots, Prefixes, Suffixes, and Combining Forms', BODY='Overview of Body', SKEL='Skeletal', MUS='Muscular', RESP='Respiratory', DIG='Digestive', CV='Cardiovascular & Lymphatic', NERV='Nervous/Special Senses', ENDO='Endocrine', REPRO='Reproductive', INTEG='Integumentary', URIN='Urinary';

export default {
 id:'medical-terminology-5',
 event:'Medical Terminology',
 title:'Practice Test 5',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Ehrlich’s Medical Terminology for Health Professions, Stanhope & Turnbull, and Taber’s Cyclopedic Medical Dictionary',
 plan:[{area:WP,weight:45},{area:BODY,weight:5},{area:SKEL,weight:5},{area:MUS,weight:5},{area:RESP,weight:5},{area:DIG,weight:5},{area:CV,weight:5},{area:NERV,weight:5},{area:ENDO,weight:5},{area:REPRO,weight:5},{area:INTEG,weight:5},{area:URIN,weight:5}],
 questions:mix([
  q(WP,'What does the suffix -penia mean?','Deficiency',['Excess','Swelling','Hardening'],'A','Leukopenia is a deficiency of white blood cells. Excess is often -osis or hyper-, swelling is edema and hardening is -sclerosis.',EHR),
  q(WP,'What does the suffix -oid mean?','Resembling',['Tumor','Removal','Opening'],'B','Lipoid means resembling fat and mucoid resembling mucus. Tumor is -oma, removal is -ectomy and opening is -stomy.',EHR),
  q(WP,'What does the suffix -spasm mean?','Sudden involuntary contraction',['Gradual loss of muscle tissue','Surgical repair of a muscle','Abnormal softening of tissue'],'C','Bronchospasm is a sudden contraction of the bronchial muscle. Atrophy is wasting, -plasty is repair and -malacia is softening.',EHR),
  q(WP,'Which suffix names an instrument used to view or examine?','-scope',['-scopy','-gram','-tome'],'D','An otoscope is an instrument to view the ear; -scopy is the process of viewing, -gram a record and -tome a cutting instrument.',EHR),
  q(WP,'What does the suffix -rrhage mean?','Bursting forth of blood',['Suturing of a wound','Flow of thin fluid','Rupture of an organ'],'A','Hemorrhage is a bursting forth of blood. Suturing is -rrhaphy, flow is -rrhea and rupture is -rrhexis.',EHR),
  q(WP,'What does the suffix -opia mean?','Vision condition',['Hearing loss','Speech problem','Smell disorder'],'B','Myopia and diplopia name vision conditions. Hearing terms use -acusis, speech -phasia and smell -osmia.',EHR),
  q(WP,'What does the suffix -kinesia mean?','Movement',['Sensation','Paralysis','Swallowing'],'C','Bradykinesia means slow movement. Sensation is -esthesia, paralysis is -plegia and swallowing is -phagia.',EHR),
  q(WP,'What does the prefix anti- mean?','Against',['Before','Around','Toward'],'D','Antibiotics act against bacteria. Before is ante- or pre-, around is peri- or circum- and toward is ad-.',EHR),
  q(WP,'What does the prefix epi- mean?','Upon or above',['Within or inside','Below or under','Between or among'],'A','The epidermis lies upon the dermis. Within is endo-, below is hypo- or sub- and between is inter-.',EHR),
  q(WP,'What does the prefix endo- mean?','Within',['Outside','Across','Beside'],'B','An endoscope views within the body. Outside is exo- or ecto-, across is trans- and beside is para-.',EHR),
  q(WP,'What does the prefix macro- mean?','Large',['Small','Many','Half'],'C','A macrocyte is an abnormally large cell. Small is micro-, many is poly- or multi- and half is hemi- or semi-.',EHR),
  q(WP,'What does the prefix mal- mean?','Bad or poor',['New or recent','Large or long','Normal or good'],'D','Malnutrition is poor nutrition and malaise a general bad feeling. New is neo-, large is macro- and good is eu-.',EHR),
  q(WP,'What does the prefix para- mean?','Beside, near or abnormal',['Through or completely','Below or deficient','After or behind'],'A','Parathyroid glands lie beside the thyroid. Through is dia-, below is hypo- and after is post-.',EHR),
  q(WP,'What does the prefix post- mean?','After or behind',['Before or in front','Within or inside','Against or opposing'],'B','Postoperative means after surgery. Before is pre- or ante-, within is endo- and against is anti- or contra-.',EHR),
  q(WP,'What does the prefix pseudo- mean?','False',['Many','Small','True'],'C','A pseudocyst is a false cyst lacking a true lining. Many is poly-, small is micro- and true has no common prefix.',EHR),
  q(WP,'What does the prefix bi- mean?','Two',['One','Three','Four'],'D','Bilateral means on two sides. One is uni- or mono-, three is tri- and four is quadri- or tetra-.',EHR),
  q(WP,'What does the combining form carcin/o mean?','Cancer',['Heart','Cartilage','Wrist'],'A','A carcinoma is a cancerous tumor of epithelial tissue. Heart is cardi/o, cartilage is chondr/o and wrist is carp/o.',EHR),
  q(WP,'What does the combining form erythr/o mean?','Red',['White','Black','Yellow'],'B','An erythrocyte is a red blood cell. White is leuk/o, black is melan/o and yellow is xanth/o.',EHR),
  q(WP,'What does the combining form gingiv/o mean?','Gums',['Tongue','Teeth','Lips'],'C','Gingivitis is inflammation of the gums. Tongue is gloss/o or lingu/o, teeth odont/o or dent/o and lips cheil/o or labi/o.',EHR),
  q(WP,'Which combining form means tongue?','gloss/o',['gnath/o','gingiv/o','cheil/o'],'D','Glossitis is inflammation of the tongue. Gnath/o means jaw, gingiv/o gums and cheil/o lips.',EHR),
  q(WP,'What does the combining form hist/o mean?','Tissue',['Cell','Bone','Blood'],'A','Histology is the study of tissues. Cell is cyt/o, bone is oste/o and blood is hem/o or hemat/o.',EHR),
  q(WP,'What does the combining form xanth/o mean?','Yellow',['Green','Blue','Red'],'B','A xanthoma is a yellow fatty skin deposit. Green is chlor/o, blue is cyan/o and red is erythr/o.',EHR),
  q(WP,'In the term “pediatrics,” what does ped/o mean?','Child',['Foot','Old age','Mind'],'C','Ped/o means child in pediatrics, though pod/o or ped/o can mean foot in other terms. Old age is ger/o and mind is psych/o.',EHR),
  q(BODY,'Which plane divides the body into equal right and left halves?','Midsagittal plane',['Transverse plane','Frontal plane','Oblique plane'],'D','The midsagittal (median) plane runs down the midline. The frontal plane makes front and back, and the transverse makes top and bottom.',EHR),
  q(BODY,'A patient lying face up on the back is in which position?','Supine',['Prone','Lateral','Fowler'],'A','Supine is lying on the back, face up; prone is face down. Fowler position is semi-sitting with the head raised.',EHR),
  q(BODY,'The wrist is ______ to the elbow.','Distal',['Proximal','Superior','Medial'],'B','Distal means farther from the point of attachment to the trunk; the wrist is farther from the shoulder than the elbow.',EHR),
  q(SKEL,'A bone that bends and cracks on one side only, common in children, has which type of fracture?','Greenstick fracture',['Comminuted fracture','Compound fracture','Compression fracture'],'C','Children’s flexible bones can break on one side like a green twig. Comminuted means splintered into pieces.',EHR),
  q(SKEL,'What is the common name for the clavicle?','Collarbone',['Shoulder blade','Breastbone','Kneecap'],'D','The clavicle is the collarbone. The scapula is the shoulder blade, the sternum the breastbone and the patella the kneecap.',EHR),
  q(MUS,'Which movement decreases the angle between two bones, as in bending the elbow?','Flexion',['Extension','Rotation','Abduction'],'A','Flexion decreases a joint angle; extension increases it. Rotation turns a bone on its axis and abduction moves away from the midline.',EHR),
  q(MUS,'Which inherited disorders cause progressive weakness and degeneration of skeletal muscle?','Muscular dystrophy',['Myasthenia gravis','Fibromyalgia','Tendinitis'],'B','Muscular dystrophies are genetic diseases of progressive muscle wasting; myasthenia gravis is an autoimmune nerve-muscle disorder.',STAN),
  q(RESP,'What is the medical term for a nosebleed?','Epistaxis',['Rhinitis','Rhinorrhea','Hemoptysis'],'C','Epistaxis is bleeding from the nose. Rhinitis is nasal inflammation, rhinorrhea is runny nose and hemoptysis is coughing blood.',EHR),
  q(RESP,'What is visual examination of the bronchi with an endoscope called?','Bronchoscopy',['Bronchiectasis','Bronchospasm','Bronchoplasty'],'D','Bronch/o + -scopy means visual examination of the bronchi; bronchiectasis is dilation and bronchospasm is contraction.',EHR),
  q(DIG,'What is surgical removal of the gallbladder called?','Cholecystectomy',['Cholecystitis','Cholelithiasis','Choledochotomy'],'A','Chol/e (bile) + cyst/o (bladder) + -ectomy (removal). Cholecystitis is inflammation and cholelithiasis is gallstones.',EHR),
  q(DIG,'What is an abnormal buildup of fluid in the abdominal cavity called?','Ascites',['Edema','Emesis','Eructation'],'B','Ascites is fluid in the peritoneal cavity, often from cirrhosis. Edema is tissue swelling, emesis vomiting and eructation belching.',EHR),
  q(DIG,'What is the presence of stones in the gallbladder called?','Cholelithiasis',['Nephrolithiasis','Choledocholithotomy','Sialolithiasis'],'C','Chol/e (bile) + lith (stone) + -iasis (condition). Nephrolithiasis is kidney stones and sialolithiasis salivary stones.',EHR),
  q(CV,'What is the surgical repair of a blood vessel, often by widening it with a balloon, called?','Angioplasty',['Angiography','Angiostenosis','Angiorrhaphy'],'D','Angi/o (vessel) + -plasty (surgical repair). Angiography records vessels, angiostenosis is narrowing and angiorrhaphy is suturing.',EHR),
  q(CV,'What is a lack of blood flow to a tissue due to a blocked artery called?','Ischemia',['Hyperemia','Leukemia','Septicemia'],'A','Isch/o (hold back) + -emia (blood). Hyperemia is excess blood, leukemia a cancer of white cells and septicemia blood infection.',EHR),
  q(NERV,'What is nearsightedness called?','Myopia',['Hyperopia','Presbyopia','Diplopia'],'B','In myopia, distant objects look blurry. Hyperopia is farsightedness, presbyopia age-related focus loss and diplopia double vision.',EHR),
  q(NERV,'What is a ringing or buzzing sound in the ears called?','Tinnitus',['Vertigo','Otalgia','Otorrhea'],'C','Tinnitus is ringing in the ears. Vertigo is a spinning sensation, otalgia ear pain and otorrhea ear discharge.',EHR),
  q(ENDO,'What is the condition of too little thyroid hormone called?','Hypothyroidism',['Hyperthyroidism','Hypoparathyroidism','Hyperparathyroidism'],'D','Hypo- (below) + thyroid + -ism (condition). It causes fatigue, weight gain and cold intolerance.',EHR),
  q(ENDO,'Which disease results from too little cortisol produced by the adrenal cortex?','Addison disease',['Cushing syndrome','Graves disease','Conn syndrome'],'A','Addison disease is adrenal insufficiency; Cushing syndrome is excess cortisol and Graves disease is hyperthyroidism.',EHR),
  q(ENDO,'What is surgical removal of the thyroid gland called?','Thyroidectomy',['Thyroiditis','Thyromegaly','Thyrotoxicosis'],'B','Thyroid + -ectomy (removal). Thyroiditis is inflammation, thyromegaly enlargement and thyrotoxicosis excess hormone.',EHR),
  q(REPRO,'What is abnormally heavy or long menstrual bleeding called?','Menorrhagia',['Amenorrhea','Dysmenorrhea','Oligomenorrhea'],'C','Men/o (menses) + -rrhagia (excessive flow). Amenorrhea is absence, dysmenorrhea pain and oligomenorrhea infrequent periods.',EHR),
  q(REPRO,'Which procedure examines the vagina and cervix with a magnifying instrument?','Colposcopy',['Laparoscopy','Cystoscopy','Hysteroscopy'],'D','Colp/o (vagina) + -scopy. Laparoscopy views the abdomen, cystoscopy the bladder and hysteroscopy the inside of the uterus.',EHR),
  q(REPRO,'An older man has a noncancerous enlargement of the prostate. What is this called?','Benign prostatic hyperplasia',['Prostatic carcinoma','Prostatitis','Cryptorchidism'],'A','BPH is an increase in the number of prostate cells (hyperplasia) that is not cancer and can block urine flow.',EHR),
  q(INTEG,'What is the medical term for hives?','Urticaria',['Eczema','Impetigo','Psoriasis'],'B','Urticaria causes raised, itchy wheals, often allergic. Eczema is itchy dermatitis, impetigo a bacterial infection and psoriasis scaly plaques.',EHR),
  q(INTEG,'What is the overproduction of oil (sebum) by the skin’s glands called?','Seborrhea',['Diaphoresis','Hirsutism','Xeroderma'],'C','Seb/o (sebum) + -rrhea (flow). Diaphoresis is sweating, hirsutism excess hair and xeroderma dry skin.',EHR),
  q(INTEG,'What is unusual paleness of the skin called?','Pallor',['Cyanosis','Jaundice','Erythema'],'D','Pallor is paleness, often from anemia or shock. Cyanosis is bluish skin, jaundice yellow and erythema red.',EHR),
  q(URIN,'What is the production of an abnormally large amount of urine called?','Polyuria',['Oliguria','Anuria','Dysuria'],'A','Poly- (much) + -uria (urine). Oliguria is scanty urine, anuria none and dysuria painful urination.',EHR),
  q(URIN,'Which procedure views the inside of the urinary bladder with a scope?','Cystoscopy',['Cystectomy','Cystocele','Cystogram'],'B','Cyst/o (bladder) + -scopy. Cystectomy removes the bladder, a cystocele is a bladder hernia and a cystogram is an X-ray record.',EHR)
 ],9502)
};
